def powermod(a, b, c):
    """Raise a number a to a power b modulus c via successive squaring"""
    if b == 0 : x = 1
    else:
        half = powermod(a, b // 2, c)
        x = half * half
        if b % 2 == 1:
            x *= a
    return x % c

