    def __init__(self):
        self.inputs = []
        self.lookahead = 0

    def parse(self, inputs: List[Token]) -> ParseTree:
        self.inputs = inputs
        self.lookahead = 0
        temp = self.stmt()
        if self.lookahead != len(self.inputs):
            raise Parser.Malformed
        else:
            return temp

    def match(self, terminal: Token):
        if terminal == self.inputs[self.lookahead]:
            self.lookahead += 1
        else:
